mapper.select:
SELECT id FROM version_release_plan
WHERE workspace_id = #{workspaceId} AND id = #{planId}
FOR UPDATE

mapper.delete:
DELETE FROM version_release_plan_task_check
WHERE workspace_id = #{workspaceId} AND plan_id = #{planId}
  AND task_id = #{taskId} AND user_id = #{userId}

mapper.update:
UPDATE version_release_plan_push
SET group_sent = #{groupSent}, group_error = #{groupError}
WHERE id = #{pushId}

UPDATE version_release_plan_push_recipient r
INNER JOIN version_release_plan_push p ON p.id = r.push_id
SET r.acked_at = CURRENT_TIMESTAMP
WHERE p.workspace_id = #{workspaceId} AND p.plan_id = #{planId}
  AND r.user_id = #{userId} AND r.acked_at IS NULL
  AND p.id = (SELECT id FROM (
    SELECT p2.id FROM version_release_plan_push p2
    WHERE p2.workspace_id = #{workspaceId} AND p2.plan_id = #{planId}
    ORDER BY p2.created_at DESC, p2.id DESC LIMIT 1
  ) latest)

mapper.select:

WHERE p.workspace_id = #{workspaceId} AND p.plan_id = #{planId}
ORDER BY p.created_at DESC, p.id DESC
LIMIT 1


WHERE p.workspace_id = #{workspaceId} AND p.plan_id = #{planId}
ORDER BY p.created_at DESC, p.id DESC
LIMIT #{limit}

SELECT p.id, p.plan_no AS planNo, MIN(pv.version_id) AS versionId, MIN(pv.req_id) AS reqId, p.planned_at AS plannedAt, p.status, p.owner_user_id AS ownerUserId, u.display_name AS ownerName, p.environment, p.coverage, GROUP_CONCAT(DISTINCT r.name ORDER BY r.name SEPARATOR '、') AS projectNames, GROUP_CONCAT(DISTINCT v.name ORDER BY v.name SEPARATOR '、') AS versionNames, COUNT(DISTINCT pv.version_id) AS versionCount, p.updated_at AS updatedAt, w.created_at AS watchedAt FROM version_release_plan_watch w INNER JOIN version_release_plan p ON p.id = w.plan_id AND p.workspace_id = w.workspace_id LEFT JOIN version_release_plan_version pv ON pv.plan_id = p.id AND pv.workspace_id = p.workspace_id LEFT JOIN requirement r ON r.id = pv.req_id AND r.workspace_id = p.workspace_id LEFT JOIN project_version v ON v.id = pv.version_id AND v.workspace_id = p.workspace_id LEFT JOIN app_user u ON u.id = p.owner_user_id WHERE w.workspace_id = #{workspaceId} AND w.user_id = #{userId}
AND EXISTS ( SELECT 1 FROM version_release_plan_version x INNER JOIN project_version vx ON vx.workspace_id = x.workspace_id AND vx.id = x.version_id WHERE x.workspace_id = w.workspace_id AND x.plan_id = w.plan_id AND NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = x.workspace_id AND pm.project_id = vx.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none') )
GROUP BY p.id, p.plan_no, p.planned_at, p.status, p.owner_user_id, u.display_name, p.environment, p.coverage, p.updated_at, w.created_at ORDER BY p.planned_at IS NULL, p.planned_at, p.updated_at DESC, p.id LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM version_release_plan_milestone
WHERE workspace_id = #{workspaceId} AND plan_id = #{planId}
  AND user_id = #{userId} AND milestone = #{milestone}

mapper.select:
SELECT COUNT(*)
FROM version_release_plan_task pt
INNER JOIN task t ON t.id = pt.task_id AND t.workspace_id = pt.workspace_id
LEFT JOIN version_release_plan_task_check c
  ON c.workspace_id = pt.workspace_id AND c.plan_id = pt.plan_id
 AND c.task_id = pt.task_id AND c.user_id = #{userId}
WHERE pt.workspace_id = #{workspaceId} AND pt.plan_id = #{planId}
  AND t.deleted_at IS NULL AND t.owner_user_id = #{userId}
  AND (c.state IS NULL OR c.scope_token <> #{scopeToken}
       OR (c.planned_at_snapshot IS NOT NULL AND #{plannedAt} IS NOT NULL
           AND c.planned_at_snapshot > #{plannedAt}))
